<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Archive, CheckCheck, Database, Download, HardDrive, LogOut, Save, ShieldCheck } from 'lucide-vue-next'
import Pager from '../components/Pager.vue'
import { api, dateTimeLabel, loadProjects, messageOf, notify, query } from '../api'
import type { Backup, Page } from '../types'
const emit=defineEmits<{changed:[]}>()
const operator=ref(''),version=ref(''),backups=ref<Backup[]>([]),backupTotal=ref(0),offset=ref(0),error=ref(''),saving=ref(false),backing=ref(false),checking=ref(false),demoing=ref(false),stopping=ref(false),stopped=ref(false),audit=ref<{ok:boolean;total:number;broken_at?:string}>();const limit=20
async function loadBackups(){const data=await api<Page<Backup>>(`/api/backups?${query({limit,offset:offset.value})}`);backups.value=data.items;backupTotal.value=data.total}
onMounted(async()=>{try{const [settings,health]=await Promise.all([api<{operator:string}>('/api/settings'),api<{version:string}>('/api/health')]);operator.value=settings.operator;version.value=health.version;await loadBackups()}catch(e){error.value=messageOf(e)}})
async function save(){saving.value=true;error.value='';try{await api('/api/settings',{method:'PUT',body:JSON.stringify({operator:operator.value})});notify('操作人已保存')}catch(e){error.value=messageOf(e)}finally{saving.value=false}}
async function backup(){backing.value=true;error.value='';try{await api('/api/backups',{method:'POST',body:'{}'});notify('备份已创建');offset.value=0;await loadBackups()}catch(e){error.value=messageOf(e)}finally{backing.value=false}}
async function verify(){checking.value=true;error.value='';try{audit.value=await api('/api/audit/verify');notify(audit.value?.ok?'审计链校验通过':'审计链校验发现异常',!audit.value?.ok)}catch(e){error.value=messageOf(e)}finally{checking.value=false}}
async function demo(){if(!window.confirm('在当前空工作空间中加载示例项目、任务、记录和问题？已有业务数据时不会执行。'))return;demoing.value=true;error.value='';try{await api('/api/demo',{method:'POST',body:'{}'});await loadProjects();notify('示例数据已加载，可以开始体验');emit('changed')}catch(e){error.value=messageOf(e)}finally{demoing.value=false}}
async function shutdown(){if(!window.confirm('确定退出 ProjNote 并停止本机服务？未保存的草稿不会保留。'))return;stopping.value=true;error.value='';try{await api('/api/system/shutdown',{method:'POST',body:'{}'});stopped.value=true}catch(e){error.value=messageOf(e)}finally{stopping.value=false}}
async function page(next:number){offset.value=next;try{await loadBackups()}catch(e){error.value=messageOf(e)}}
function size(value:number){return value<1024?`${value} B`:value<1024*1024?`${(value/1024).toFixed(1)} KB`:`${(value/1024/1024).toFixed(1)} MB`}
</script>
<template><div class="page-heading"><div><h1>设置与备份</h1><p class="page-description">工作空间由你掌管，重要资料定期留一份副本。</p></div><span class="version-label" v-if="version">ProjNote {{version}}</span></div><div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-if="stopped" class="shutdown-state surface"><CheckCheck :size="36"/><h2>本机服务已停止</h2><p>可以关闭此页面。下次启动 ProjNote 后即可继续使用。</p></div><div v-else class="settings-layout"><section class="surface settings-panel"><div class="section-heading"><h2>工作空间</h2><HardDrive :size="18"/></div><form class="settings-body" @submit.prevent="save"><label>操作人<input v-model="operator" required maxlength="100" placeholder="姓名或称呼"/></label><p class="input-hint">记录在问题流转和审计日志中，便于追溯每次操作。</p><button class="button primary small" :disabled="saving"><Save :size="15"/>{{saving?'正在保存…':'保存设置'}}</button></form><div class="settings-block"><div class="setting-icon"><Database :size="20"/></div><div><h3>从示例了解工作流程</h3><p>加载一组示例项目、任务、现场记录和问题，仅支持空工作空间。</p><button class="button subtle small" :disabled="demoing" @click="demo">{{demoing?'正在加载…':'加载示例数据'}}</button></div></div><div class="settings-block"><div class="setting-icon"><ShieldCheck :size="20"/></div><div><h3>操作审计校验</h3><p>核对审计记录的连续性，检查操作历史是否完整。</p><button class="button subtle small" :disabled="checking" @click="verify">{{checking?'正在校验…':'校验审计链'}}</button><p v-if="audit" class="audit-result" :class="{invalid:!audit.ok}" role="status">{{audit.ok?`校验通过，共 ${audit.total} 条审计记录`:`发现异常，位置：${audit.broken_at||'未知'}`}}</p></div></div><div class="settings-block"><div class="setting-icon"><LogOut :size="20"/></div><div><h3>退出 ProjNote</h3><p>只关闭浏览器不会停止服务。结束本次工作时，可在这里退出。</p><button class="button subtle small" :disabled="stopping" @click="shutdown">{{stopping?'正在退出…':'退出并停止服务'}}</button></div></div></section><section class="surface settings-panel"><div class="section-heading"><h2>数据备份 <span class="count">{{backupTotal}}</span></h2><button class="button primary small" :disabled="backing" @click="backup"><Archive :size="15"/>{{backing?'正在创建…':'创建备份'}}</button></div><div class="backup-description"><p>备份包含数据库与附件。创建后可下载到其他磁盘，保留独立副本。</p><span class="input-hint">恢复备份需先退出服务，再用启动程序的 --restore 参数执行。</span></div><div v-if="!backups.length" class="empty-state compact"><Archive :size="32"/><h3>还没有备份</h3><p>完成重要工作后，创建一份资料副本。</p><button class="button subtle small" :disabled="backing" @click="backup">创建第一份备份</button></div><ul v-else class="backup-list"><li v-for="b in backups" :key="b.name"><div class="backup-file"><Archive :size="22"/><div><strong>{{b.name}}</strong><span>{{dateTimeLabel(b.created_at)}}　{{size(b.size)}}</span></div></div><a class="button subtle small" :href="`/api/backups/${encodeURIComponent(b.name)}/download`" :download="b.name" :aria-label="`下载备份 ${b.name}`"><Download :size="16"/>下载</a></li></ul><Pager :offset="offset" :limit="limit" :total="backupTotal" @change="page"/></section></div></template>
